import java.util.*;
class SCC {final List<List<Integer>> adj;final List<List<Integer>> groups=new ArrayList<>();final int[] index,low;final boolean[] active;final ArrayDeque<Integer> stack=new ArrayDeque<>();int time;SCC(List<List<Integer>> adj,boolean tarjan){this.adj=adj;int n=adj.size();index=new int[n];low=new int[n];active=new boolean[n];Arrays.fill(index,-1);if(tarjan){for(int u=0;u<n;u++)if(index[u]==-1)visit(u);}else kosaraju();}
void visit(int u){index[u]=low[u]=time++;stack.push(u);active[u]=true;for(int v:adj.get(u)){if(index[v]==-1){visit(v);low[u]=Math.min(low[u],low[v]);}else if(active[v])low[u]=Math.min(low[u],index[v]);}if(low[u]==index[u]){List<Integer> g=new ArrayList<>();int v;do{v=stack.pop();active[v]=false;g.add(v);}while(v!=u);groups.add(g);}}
void finish(int u,boolean[] seen,List<Integer> out){seen[u]=true;for(int v:adj.get(u))if(!seen[v])finish(v,seen,out);out.add(u);}
void kosaraju(){int n=adj.size();boolean[] seen=new boolean[n];List<Integer> out=new ArrayList<>();List<List<Integer>> reverse=new ArrayList<>();for(int i=0;i<n;i++)reverse.add(new ArrayList<>());for(int u=0;u<n;u++)for(int v:adj.get(u))reverse.get(v).add(u);for(int u=0;u<n;u++)if(!seen[u])finish(u,seen,out);Arrays.fill(seen,false);Collections.reverse(out);
for(int seed:out){if(seen[seed])continue;List<Integer> g=new ArrayList<>();stack.push(seed);seen[seed]=true;while(!stack.isEmpty()){int u=stack.pop();g.add(u);for(int v:reverse.get(u))if(!seen[v]){seen[v]=true;stack.push(v);}}groups.add(g);}}}
